package com.angle.trading.test.finalvartest;import java.io.*;public class SerializeAndTransientWithFinal {    public static void main(String[] args) throws IOException, ClassNotFoundException {        Person1 p=new Person1("bhanu");        ObjectOutputStream objectOutputStream=new ObjectOutputStream(new FileOutputStream("per.ser") );        objectOutputStream.writeObject(p);        ObjectInputStream in =                new ObjectInputStream(new FileInputStream("per.ser"));        Person1 p2 = (Person1) in.readObject();        System.out.println(p2.getAge());    }}class Person1 implements Serializable{    private  String name;    private transient final int age;    public  Person1(String name){        this.name=name;        this.age=30;    }    public String getName() {        return name;    }    public int getAge() {        return age;    }}